/*
 * CampsiteRatingRepository.kt
 * Purpose: Firestore persistence for US 01.13.01 and consistent admin removal.
 * ratings/{reservationId} holds one score per stay. Every mutation updates the
 * campsite's ratingSum, ratingCount and displayed rating in the same transaction.
 * Existing console-created rating documents are included when totals initialize.
 * No background migration or new index is required.
 */
package com.example.code.data

import com.example.code.controller.ratingFromDocument
import com.example.code.controller.validateStayRating
import com.example.code.model.Rating
import com.google.firebase.firestore.DocumentReference
import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.Source
import com.google.firebase.firestore.Transaction
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow

/** The entrant reads their own scores and upserts a rating identified by a saved stay. */
interface CampsiteRatingStore {
    fun observeRatings(campsiteId: String, entrantId: String): Flow<List<Rating>>
    suspend fun saveRating(campsiteId: String, reservationId: String, entrantId: String, score: Int)
}

/** Integer totals avoid rounding drift when scores are changed or removed. */
internal data class RatingTotals(val sum: Long, val count: Long) {
    val average: Double? get() = if (count == 0L) null else sum.toDouble() / count
}

/** Replacing a score changes its contribution without increasing the number of ratings. */
internal fun updatedRatingTotals(totals: RatingTotals, oldScore: Int?, newScore: Int?): RatingTotals {
    require(totals.count >= 0 && (oldScore == null || totals.count > 0)) { "Invalid rating totals." }
    val updated = RatingTotals(
        sum = totals.sum - (oldScore?.toLong() ?: 0L) + (newScore?.toLong() ?: 0L),
        count = totals.count - (if (oldScore == null) 0L else 1L) + (if (newScore == null) 0L else 1L),
    )
    require(updated.sum >= 0 && (updated.count != 0L || updated.sum == 0L)) { "Invalid rating totals." }
    return updated
}

/** Fields shared with existing admin rating readers; older documents omit reservationId. */
internal fun stayRatingToMap(rating: Rating): Map<String, Any> = mapOf(
    "entrantId" to rating.entrantId,
    "campsiteId" to rating.campsiteId,
    "reservationId" to rating.reservationId,
    "score" to rating.score,
)

/** Uses server data and Firestore retries to serialize submissions and admin removals. */
class FirestoreCampsiteRatingRepository(
    private val db: FirebaseFirestore = FirebaseFirestore.getInstance(),
) : CampsiteRatingStore {
    private val ratings = db.collection("ratings")
    private val campsites = db.collection("campsites")

    override fun observeRatings(campsiteId: String, entrantId: String): Flow<List<Rating>> = callbackFlow {
        // A single equality query avoids requiring a composite Firestore index.
        val listener = ratings.whereEqualTo("entrantId", entrantId).addSnapshotListener { snapshot, error ->
            if (error != null) {
                close(error)
                return@addSnapshotListener
            }
            trySend(snapshot?.documents.orEmpty().mapNotNull { document ->
                document.data?.let { ratingFromDocument(document.id, it) }
            }.filter { it.campsiteId == campsiteId })
        }
        awaitClose { listener.remove() }
    }

    override suspend fun saveRating(campsiteId: String, reservationId: String, entrantId: String, score: Int) {
        require(listOf(campsiteId, reservationId, entrantId).all(::validRatingId)) { "A saved stay is required." }
        require(score in 1..5) { "Choose a rating from 1 to 5." }
        val bootstrap = bootstrapReferences(campsiteId)
        val campsiteRef = campsites.document(campsiteId)
        val ratingRef = ratings.document(reservationId)
        val reservationRef = db.collection("reservations").document(reservationId)
        val profileRef = db.collection(FirestoreUserRepository.USERS).document(entrantId)
        db.runTransaction { transaction ->
            val campsite = transaction.get(campsiteRef)
            val savedStay = transaction.get(reservationRef)
            val profile = transaction.get(profileRef)
            val previous = transaction.get(ratingRef)
            check(campsite.exists()) { "This campsite is unavailable." }
            check(savedStay.exists()) { "This stay is unavailable." }
            check(profile.exists() && profile.getBoolean("isActive") != false && profile.get("deletedAt") == null) {
                "Your profile is unavailable."
            }
            validateStayRating(
                reservationFromMap(savedStay.id, savedStay.data.orEmpty()),
                campsiteId, entrantId, score, System.currentTimeMillis(),
            )
            val old = previous.data?.let { ratingFromDocument(previous.id, it) }
            check(!previous.exists() || (old != null && old.reservationId == reservationId &&
                    old.campsiteId == campsiteId && old.entrantId == entrantId)) {
                "This rating does not belong to the selected stay."
            }
            // Bootstrap reads also precede writes. If another mutation initializes
            // totals first, the retried transaction uses the saved totals instead.
            val totals = readTotals(transaction, campsite, bootstrap)
            val next = updatedRatingTotals(totals, old?.score, score)
            transaction.set(ratingRef, stayRatingToMap(Rating(
                id = reservationId, entrantId = entrantId, campsiteId = campsiteId,
                score = score, reservationId = reservationId,
            )))
            transaction.update(campsiteRef, totalsToMap(next))
        }.awaitResult()
    }

    /** Reads the current score, so a stale admin screen cannot corrupt the average. */
    suspend fun removeRating(rating: Rating) {
        require(validRatingId(rating.id) && validRatingId(rating.campsiteId)) { "A saved rating is required." }
        val bootstrap = bootstrapReferences(rating.campsiteId)
        val campsiteRef = campsites.document(rating.campsiteId)
        val ratingRef = ratings.document(rating.id)
        db.runTransaction { transaction ->
            val campsite = transaction.get(campsiteRef)
            val saved = transaction.get(ratingRef)
            if (saved.exists()) {
                check(campsite.exists()) { "This campsite is unavailable." }
                val current = requireNotNull(saved.data?.let { ratingFromDocument(saved.id, it) })
                check(current.campsiteId == rating.campsiteId) { "This rating belongs to another campsite." }
                val totals = readTotals(transaction, campsite, bootstrap)
                val next = updatedRatingTotals(totals, current.score, null)
                transaction.delete(ratingRef)
                transaction.update(campsiteRef, totalsToMap(next))
            }
        }.awaitResult()
    }

    /** Query only for older campsites without totals; all discovered records are re-read in the transaction. */
    private suspend fun bootstrapReferences(campsiteId: String): List<DocumentReference>? {
        val campsite = campsites.document(campsiteId).get(Source.SERVER).awaitResult()
        if (persistedTotals(campsite) != null) return null
        return ratings.whereEqualTo("campsiteId", campsiteId).get(Source.SERVER).awaitResult()
            .documents.map { it.reference }
    }

    private fun readTotals(
        transaction: Transaction,
        campsite: DocumentSnapshot,
        bootstrap: List<DocumentReference>?,
    ): RatingTotals {
        persistedTotals(campsite)?.let { return it }
        // Refuse a partial aggregate if another client removed the totals after
        // preflight. A retry will discover and read all legacy rating documents.
        val references = checkNotNull(bootstrap) { "Campsite ratings changed. Please try again." }
        val scores = references.mapNotNull { ref ->
            val saved = transaction.get(ref)
            if (saved.getString("campsiteId") == campsite.id) (saved.get("score") as? Number)?.toInt() ?: 0 else null
        }
        return RatingTotals(scores.sumOf { it.toLong() }, scores.size.toLong())
    }

    private fun persistedTotals(campsite: DocumentSnapshot): RatingTotals? {
        val sum = campsite.getLong("ratingSum") ?: return null
        val count = campsite.getLong("ratingCount") ?: return null
        check(sum >= 0 && count >= 0 && (count != 0L || sum == 0L)) { "Invalid saved rating totals." }
        return RatingTotals(sum, count)
    }

    private fun totalsToMap(totals: RatingTotals): Map<String, Any?> = mapOf(
        "ratingSum" to totals.sum,
        "ratingCount" to totals.count,
        "rating" to totals.average,
        // Old test campsites may retain this alias; the app uses the canonical rating field.
        "averageRating" to FieldValue.delete(),
    )
}

private fun validRatingId(id: String): Boolean = id.isNotBlank() && '/' !in id && id != "." && id != ".."
